import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { booksAPI } from '../utils/api';

const Dashboard = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [bookTitle, setBookTitle] = useState('');
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    // Get user from localStorage
    const storedUser = localStorage.getItem('giftOfReadingUser');
    if (!storedUser) {
      navigate('/login');
      return;
    }

    const userData = JSON.parse(storedUser);
    setUser(userData);
    fetchUserBooks(userData._id);
  }, [navigate]);

  const fetchUserBooks = async (userId) => {
    try {
      const response = await booksAPI.getUserBooks(userId);
      setBooks(response.data.books);
      setLoading(false);
    } catch (err) {
      console.error('Error fetching books:', err);
      setLoading(false);
    }
  };

  const handleSubmitBook = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!bookTitle.trim()) {
      setError('Please enter a book title');
      return;
    }

    setSubmitting(true);

    try {
      await booksAPI.addBook(user._id, bookTitle.trim());
      setSuccess('Book added successfully! 🎉');
      setBookTitle('');
      
      // Refresh book list and update user count
      fetchUserBooks(user._id);
      
      // Update user's book count in state
      setUser(prev => ({
        ...prev,
        booksReadCount: (prev.booksReadCount || 0) + 1
      }));

      // Clear success message after 3 seconds
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError('Failed to add book. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('giftOfReadingUser');
    navigate('/');
  };

  if (loading) {
    return (
      <div className="loading">
        <div className="spinner"></div>
        <p>Loading your dashboard...</p>
      </div>
    );
  }

  if (!user) {
    return null;
  }

  return (
    <div>
      <div className="header">
        <div className="header-content" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h1>📚 Your Reading Dashboard</h1>
            <p>Gift of Reading Initiative</p>
          </div>
          <button onClick={handleLogout} className="btn btn-secondary">
            Logout
          </button>
        </div>
      </div>

      <div className="container">
        {/* Welcome Card */}
        <div className="card" style={{ 
          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
          color: 'white'
        }}>
          <h2 style={{ fontSize: '2rem', marginBottom: '10px' }}>
            Welcome, {user.firstName}! 👋
          </h2>
          <p style={{ fontSize: '1.1rem', opacity: 0.9 }}>
            {user.location}
          </p>
          {user.category === 'Student' && user.class !== 'N/A' && (
            <p style={{ fontSize: '1rem', opacity: 0.9 }}>
              Class: {user.class}
            </p>
          )}
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
          {/* Personal Tracker */}
          <div className="card">
            <h3 style={{ marginBottom: '20px', color: '#333' }}>📊 Your Reading Journey</h3>
            <div style={{ textAlign: 'center' }}>
              <div style={{ 
                display: 'inline-block',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: 'white',
                padding: '30px',
                borderRadius: '50%',
                width: '150px',
                height: '150px',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                marginBottom: '20px'
              }}>
                <div style={{ fontSize: '3rem', fontWeight: 'bold' }}>
                  {user.booksReadCount || 0}
                </div>
                <div style={{ fontSize: '0.9rem' }}>
                  Books Read
                </div>
              </div>
              <p style={{ color: '#666', fontSize: '1.1rem' }}>
                {user.booksReadCount > 0 
                  ? `🎉 Great job! Keep reading!` 
                  : `📖 Start your reading journey today!`}
              </p>
            </div>
          </div>

          {/* Add Book Form */}
          <div className="card">
            <h3 style={{ marginBottom: '20px', color: '#333' }}>➕ Record a New Book</h3>
            
            {error && <div className="error">{error}</div>}
            {success && <div className="success">{success}</div>}

            <form onSubmit={handleSubmitBook}>
              <div className="form-group">
                <label>Book Title</label>
                <input
                  type="text"
                  value={bookTitle}
                  onChange={(e) => setBookTitle(e.target.value)}
                  placeholder="Enter the book you've read"
                  disabled={submitting}
                />
              </div>
              <button 
                type="submit" 
                className="btn" 
                style={{ width: '100%' }}
                disabled={submitting}
              >
                {submitting ? 'Adding...' : 'Add Book ✓'}
              </button>
            </form>
          </div>
        </div>

        {/* Recent Readings */}
        <div className="card">
          <h3 style={{ marginBottom: '20px', color: '#333' }}>
            📚 Your Reading History ({books.length} books)
          </h3>
          
          {books.length === 0 ? (
            <div style={{ 
              textAlign: 'center', 
              padding: '40px',
              background: '#f8f9fa',
              borderRadius: '10px'
            }}>
              <div style={{ fontSize: '3rem', marginBottom: '15px' }}>📖</div>
              <p style={{ color: '#666', fontSize: '1.1rem' }}>
                No books recorded yet. Start adding the books you've read!
              </p>
            </div>
          ) : (
            <div style={{ maxHeight: '400px', overflowY: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ background: '#f8f9fa' }}>
                    <th style={{ padding: '12px', textAlign: 'left', borderBottom: '2px solid #e0e0e0' }}>#</th>
                    <th style={{ padding: '12px', textAlign: 'left', borderBottom: '2px solid #e0e0e0' }}>Book Title</th>
                    <th style={{ padding: '12px', textAlign: 'left', borderBottom: '2px solid #e0e0e0' }}>Date Recorded</th>
                  </tr>
                </thead>
                <tbody>
                  {books.map((book, index) => (
                    <tr key={book._id} style={{ borderBottom: '1px solid #f0f0f0' }}>
                      <td style={{ padding: '12px' }}>{books.length - index}</td>
                      <td style={{ padding: '12px', fontWeight: '500' }}>📖 {book.bookTitle}</td>
                      <td style={{ padding: '12px', color: '#666' }}>
                        {new Date(book.recordedAt).toLocaleDateString('en-US', {
                          year: 'numeric',
                          month: 'short',
                          day: 'numeric'
                        })}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Quick Links */}
        <div className="card" style={{ textAlign: 'center' }}>
          <button 
            onClick={() => navigate('/')}
            className="btn"
          >
